import{_ as n,o as h,c as i,a6 as d}from"./chunks/framework.BIQm0xy3.js";const s=JSON.parse('{"title":"Phụ lục D. Đối chiếu với tám tuần lý thuyết","description":"","frontmatter":{"title":"Phụ lục D. Đối chiếu với tám tuần lý thuyết"},"headers":[],"relativePath":"phu-luc-d.md","filePath":"phu-luc-d.md"}'),c={name:"phu-luc-d.md"};function a(r,t,g,o,e,u){return h(),i("div",null,[...t[0]||(t[0]=[d('<p class="eyebrow">Phụ lục D</p><h1 id="đoi-chieu-voi-tam-tuan-ly-thuyet" tabindex="-1">Đối chiếu với tám tuần lý thuyết <a class="header-anchor" href="#đoi-chieu-voi-tam-tuan-ly-thuyet" aria-label="Permalink to &quot;Đối chiếu với tám tuần lý thuyết&quot;">​</a></h1><p>Phụ lục này để bạn biết chính xác chỗ nào của sách dựa vào bài giảng nào, chỗ nào sách phải dạy thêm, và chỗ nào bài giảng có mà sách bỏ qua. Dùng nó khi ôn thi: gặp phần khó thì mở lại đúng tuần lý thuyết tương ứng.</p><h2 id="d-1-bai-giang-day-gi-sach-dung-o-đau" tabindex="-1">D.1 Bài giảng dạy gì, sách dùng ở đâu <a class="header-anchor" href="#d-1-bai-giang-day-gi-sach-dung-o-đau" aria-label="Permalink to &quot;D.1 Bài giảng dạy gì, sách dùng ở đâu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tuần</th><th>Nội dung bài giảng</th><th>Sách</th></tr></thead><tbody><tr><td>1</td><td>Giới thiệu OOP; procedural vs hướng đối tượng; robustness / adaptability / reusability; tam giác P.I.E; link cài VS Code + MinGW</td><td>0.6, 1.1, 6.5</td></tr><tr><td>2</td><td>Hello world; tool-chain; ba loại lỗi syntax / runtime / logic; bốn lỗi thường gặp</td><td>1.2, 1.6</td></tr><tr><td>3</td><td>bool, if, switch; hàm: prototype, nạp chồng, tham số mặc định, inline, phạm vi, static cục bộ; tham chiếu và truyền tham chiếu; tham chiếu hằng</td><td>1.3, 2.3</td></tr><tr><td>4</td><td>Lớp và đối tượng; sơ đồ UML và ký hiệu; struct; constructor và danh sách khởi tạo; toán tử chấm; tách .h / .cpp với #ifndef; mảng đối tượng</td><td>1.3, 1.4, 2.2, 2.3, 2.5</td></tr><tr><td>5</td><td>Đóng gói; getter/setter; public / protected / private; tiền và hậu điều kiện; this; hàm thành viên static</td><td>3.1 – 3.4</td></tr><tr><td>6</td><td>Kế thừa; quan hệ is-a; điều khiển truy cập khi kế thừa; thứ tự constructor và destructor; truyền tham số cho constructor lớp cha; redefining; các kiểu cấu trúc kế thừa; friend</td><td>4.1 – 4.6</td></tr><tr><td>7</td><td>Đa hình; liên kết tĩnh và liên kết động; virtual; hàm thuần ảo; mảng con trỏ lớp cha; destructor ảo; truyền lớp cha theo giá trị (slicing)</td><td>5.1 – 5.5</td></tr><tr><td>8</td><td>Lớp trừu tượng; ngoại lệ: throw / try / catch, thứ tự nhánh catch, std::exception và what(), ném lại, bảo đảm an toàn ngoại lệ</td><td>6.1 – 6.2, 7.1 – 7.6</td></tr><tr><td>phụ</td><td>Bộ slide Pointer: con trỏ cơ bản, mảng và con trỏ, truyền con trỏ vào hàm, trả về con trỏ</td><td>3.5, 5.3</td></tr></tbody></table><h2 id="d-2-ba-cho-đe-thi-đoi-ma-bai-giang-chua-day" tabindex="-1">D.2 Ba chỗ đề thi đòi mà bài giảng chưa dạy <a class="header-anchor" href="#d-2-ba-cho-đe-thi-đoi-ma-bai-giang-chua-day" aria-label="Permalink to &quot;D.2 Ba chỗ đề thi đòi mà bài giảng chưa dạy&quot;">​</a></h2><p>Đây là kết quả của việc rà lại toàn bộ tám tuần slide cộng hai bộ slide Pointer. Ba mục dưới đây <strong>không xuất hiện</strong> trong bất kỳ slide nào, nhưng đều cần để làm được đề thi:</p><table tabindex="0"><thead><tr><th>Thứ còn thiếu</th><th>Bằng chứng</th><th>Sách dạy ở</th></tr></thead><tbody><tr><td><code>new</code> / <code>delete</code></td><td>Không slide nào có. Tuần 7 chỉ nhắc chữ “delete operator” khi giải thích destructor ảo.</td><td>Mục 3.5</td></tr><tr><td><code>std::vector</code></td><td>Xuất hiện 0 lần trong 8 tuần slide. Đề thi ghi rõ “Tạo vector chứa Vehicle*”.</td><td>Mục 5.4</td></tr><tr><td>Lỗi liên kết</td><td>Tuần 2 chia lỗi thành 3 loại, không có loại này. Nó chỉ xuất hiện khi tách nhiều file, tức là từ tuần 4.</td><td><a href="./chuong-1.html#_1-6-bon-loai-loi-va-cach-phan-biet">Mục 1.6</a></td></tr></tbody></table><div class="hop ghi-chu"><p class="hop-tieu-de">Gợi ý cho người dạy</p><p>Ba chỗ trên đáng được bổ sung vào bài giảng, dù chỉ vài slide. Chúng nằm đúng trên đường đi tới điểm “chương trình chạy đúng” (3 điểm) — phần mà trung bình lớp đang hụt nhiều nhất.</p><p>Nếu không kịp bổ sung vào slide, ít nhất nên nhắc sinh viên đọc trước mục 3.5 và 5.4 của sách này trước buổi thực hành tuần 5.</p></div><h2 id="d-3-bai-giang-co-sach-khong-dung" tabindex="-1">D.3 Bài giảng có, sách không dùng <a class="header-anchor" href="#d-3-bai-giang-co-sach-khong-dung" aria-label="Permalink to &quot;D.3 Bài giảng có, sách không dùng&quot;">​</a></h2><p>Không mục nào dưới đây xuất hiện trong thang điểm của 12 đề thi gần nhất, nên sách bỏ qua để tập trung thời gian. Chúng vẫn đáng học khi đã qua môn:</p><ul><li><strong>Hàm thành viên static</strong> (tuần 5) — biến dùng chung cho mọi đối tượng của lớp.</li><li><strong>Tiền và hậu điều kiện</strong> (tuần 5) — cách viết hợp đồng của một phương thức.</li><li><strong>friend class</strong> (tuần 6). Sách chỉ dùng <code>friend</code> đúng một lần cho hàm <code>operator&lt;&lt;</code> ở mục 5.6 — đó là ứng dụng phổ biến nhất của từ khoá này.</li><li><strong>Kế thừa phân cấp, đa kế thừa dữ liệu, kế thừa lai</strong> (tuần 6). Sách dùng kế thừa đơn, kế thừa nhiều tầng và đa kế thừa <strong>giao diện</strong> — đúng ba kiểu mà đề thi hỏi.</li><li><strong>Ném lại ngoại lệ và bảo đảm an toàn ngoại lệ</strong> (tuần 8) — mức nâng cao, đề thi chỉ yêu cầu bắt và xử lý.</li><li><strong>Hàm inline, tham số mặc định, static cục bộ</strong> (tuần 3).</li></ul><h2 id="d-4-thuat-ngu-dung-thong-nhat" tabindex="-1">D.4 Thuật ngữ dùng thống nhất <a class="header-anchor" href="#d-4-thuat-ngu-dung-thong-nhat" aria-label="Permalink to &quot;D.4 Thuật ngữ dùng thống nhất&quot;">​</a></h2><p>Sách cố ý dùng lại đúng từ của bài giảng để bạn không phải nhớ hai bộ từ vựng:</p><table tabindex="0"><thead><tr><th>Bài giảng</th><th>Sách</th><th>Ở mục</th></tr></thead><tbody><tr><td>static binding / dynamic binding</td><td>liên kết tĩnh / liên kết động</td><td>5.1</td></tr><tr><td>redefining</td><td>định nghĩa lại (phân biệt với nạp chồng)</td><td>4.6</td></tr><tr><td>pure virtual function</td><td>hàm thuần ảo</td><td>6.2</td></tr><tr><td>abstract class</td><td>lớp trừu tượng</td><td>6.2</td></tr><tr><td>getter / accessor, setter / mutator</td><td>getter, setter</td><td>3.3</td></tr><tr><td>UML: dấu −, +, #; kiểu ghi sau tên; {virtual}, {abstract}</td><td>giữ nguyên ký hiệu đó</td><td>2.5</td></tr><tr><td>syntax / runtime / logic error</td><td>lỗi cú pháp / lúc chạy / logic (thêm: lỗi liên kết)</td><td>1.6</td></tr></tbody></table>',15)])])}const b=n(c,[["render",a]]);export{s as __pageData,b as default};
